{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Oral fludarabine phosphate as immediate-release tablets gave dose-independent systemic availability of approximately 55% versus IV in patients, directly supporting high oral bioavailability for 2-fluoroadenine nucleosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Fludarabine monophosphate showed 70% absolute oral bioavailability in humans, demonstrating efficient oral absorption of a 2-fluoroadenine nucleoside.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "MK-8591, a 2-fluoroadenine nucleoside analog with a deoxy-modified sugar, was characterized as having high oral bioavailability at low oral doses.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Clofarabine, a 2-haloadenine nucleoside, had 49% absolute oral bioavailability in patients with solid tumors, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Cladribine, a 2-chloroadenine deoxyriboside, had absolute oral bioavailability of 35.3% in patients, supporting high oral absorption for halogenated adenine nucleosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Oral administration of fludarabine injectable solution gave approximately 70% bioavailability in humans, reinforcing high oral absorption for fluorinated adenine nucleosides.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a 2-fluoroadenine nucleoside analog. Closely related 2-fluoroadenine and 2-haloadenine nucleosides—fludarabine, clofarabine, cladribine, and islatravir—consistently show oral bioavailability well above 20% (approximately 35–75%). The query's less polar, deoxy-modified sugar is unlikely to reduce absorption below the threshold, so high oral bioavailability is predicted.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the exact query molecule.",
    "The effect of the missing 5'-hydroxymethyl group on transporter-mediated absorption and metabolic stability is not directly characterized.",
    "Low-bioavailability records for ATP, S-adenosylmethionine, and didanosine come from structurally distant molecules with different absorption/metabolic liabilities and are not transferable to this 2-fluoroadenine nucleoside."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

